namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeCategory
{
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public string Icon { get; set; } = string.Empty;
}

using System.ComponentModel.DataAnnotations;

namespace RecipeCommunity.Models;

public class RecipeSubmission
{
    [Required(ErrorMessage = "Title is required")]
    [StringLength(100, MinimumLength = 3, ErrorMessage = "Title must be between 3 and 100 characters")]
    public string Title { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a category")]
    public string Category { get; set; } = string.Empty;

    [Required(ErrorMessage = "Ingredients are required")]
    [MinLength(10, ErrorMessage = "Please provide more detail for ingredients")]
    public string Ingredients { get; set; } = string.Empty;

    [Required(ErrorMessage = "Steps are required")]
    [MinLength(10, ErrorMessage = "Please provide more detail for the steps")]
    public string Steps { get; set; } = string.Empty;
}

using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private readonly List<RecipeCategory> _categories;

    public RecipeService()
    {
        _categories = new List<RecipeCategory>
        {
            new() { Name = "Breakfast", Description = "Start your day right with these morning favorites", Icon = "🍳" },
            new() { Name = "Lunch", Description = "Quick and satisfying midday meals", Icon = "🥪" },
            new() { Name = "Dinner", Description = "Hearty evening recipes for the whole family", Icon = "🍝" },
            new() { Name = "Desserts", Description = "Sweet treats to end any meal", Icon = "🍰" },
            new() { Name = "Vegetarian", Description = "Delicious plant-based dishes", Icon = "🥗" },
            new() { Name = "Quick & Easy", Description = "Ready in 30 minutes or less", Icon = "⚡" }
        };

        _recipes = new List<Recipe>
        {
            new()
            {
                Id = 1, Title = "Classic Pancakes", Category = "Breakfast",
                Ingredients = "2 cups flour\n2 eggs\n1.5 cups milk\n2 tbsp sugar\n1 tsp baking powder\nPinch of salt\nButter for cooking",
                Steps = "1. Mix dry ingredients in a bowl\n2. Whisk eggs and milk together\n3. Combine wet and dry ingredients until just mixed\n4. Heat a buttered pan over medium heat\n5. Pour batter and cook until bubbles form, then flip\n6. Serve with maple syrup and fresh berries",
                AverageRating = 4.5, RatingCount = 12
            },
            new()
            {
                Id = 2, Title = "Spaghetti Carbonara", Category = "Dinner",
                Ingredients = "400g spaghetti\n200g pancetta\n4 egg yolks\n100g Pecorino Romano\n2 cloves garlic\nBlack pepper",
                Steps = "1. Cook spaghetti in salted boiling water\n2. Fry pancetta until crispy\n3. Mix egg yolks with grated cheese and pepper\n4. Toss hot pasta with pancetta\n5. Remove from heat and stir in egg mixture\n6. Serve immediately with extra cheese",
                AverageRating = 4.8, RatingCount = 24
            },
            new()
            {
                Id = 3, Title = "Caesar Salad", Category = "Lunch",
                Ingredients = "1 head romaine lettuce\nCroutons\nParmesan cheese\nCaesar dressing\nLemon juice\nAnchovy fillets (optional)",
                Steps = "1. Wash and chop romaine lettuce\n2. Prepare croutons by toasting bread cubes\n3. Toss lettuce with Caesar dressing\n4. Top with croutons and shaved Parmesan\n5. Add a squeeze of lemon juice\n6. Serve immediately",
                AverageRating = 4.2, RatingCount = 8
            },
            new()
            {
                Id = 4, Title = "Chocolate Lava Cake", Category = "Desserts",
                Ingredients = "200g dark chocolate\n150g butter\n3 eggs\n100g sugar\n50g flour\nPinch of salt",
                Steps = "1. Melt chocolate and butter together\n2. Whisk eggs and sugar until fluffy\n3. Fold chocolate mixture into eggs\n4. Add flour and salt, fold gently\n5. Pour into greased ramekins\n6. Bake at 200°C for 12 minutes\n7. Invert onto plates and serve immediately",
                AverageRating = 4.9, RatingCount = 31
            },
            new()
            {
                Id = 5, Title = "Veggie Stir Fry", Category = "Vegetarian",
                Ingredients = "Mixed vegetables (bell peppers, broccoli, snap peas)\nTofu\nSoy sauce\nSesame oil\nGarlic and ginger\nRice",
                Steps = "1. Press and cube tofu\n2. Cook rice according to package directions\n3. Heat sesame oil in a wok\n4. Stir-fry tofu until golden\n5. Add vegetables and stir-fry 3-4 minutes\n6. Add soy sauce, garlic, and ginger\n7. Serve over rice",
                AverageRating = 4.3, RatingCount = 15
            },
            new()
            {
                Id = 6, Title = "15-Minute Garlic Shrimp", Category = "Quick & Easy",
                Ingredients = "500g shrimp, peeled\n4 cloves garlic\nButter\nLemon juice\nParsley\nSalt and pepper",
                Steps = "1. Heat butter in a large skillet\n2. Add minced garlic, cook 30 seconds\n3. Add shrimp in a single layer\n4. Cook 2 minutes per side\n5. Squeeze lemon juice over shrimp\n6. Garnish with parsley and serve",
                AverageRating = 4.6, RatingCount = 19
            }
        };
    }

    public List<RecipeCategory> GetCategories() => _categories;

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipeById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe != null)
        {
            var totalStars = recipe.AverageRating * recipe.RatingCount + stars;
            recipe.RatingCount++;
            recipe.AverageRating = Math.Round(totalStars / recipe.RatingCount, 1);
        }
    }

    public void SubmitRecipe(RecipeSubmission submission)
    {
        var newId = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(new Recipe
        {
            Id = newId,
            Title = submission.Title,
            Category = submission.Category,
            Ingredients = submission.Ingredients,
            Steps = submission.Steps,
            AverageRating = 0,
            RatingCount = 0
        });
    }
}

