@page "/category/{CategoryName}"
@using RecipeCommunity.Services
@using RecipeCommunity.Models

@inject RecipeService RecipeService

<PageTitle>@CategoryName Recipes - Recipe Community</PageTitle>

<div class="container">
    <nav class="breadcrumb">
        <a href="/">Home</a> &rsaquo; <span>@CategoryName</span>
    </nav>

    <h1>@CategoryName Recipes</h1>

    @if (Recipes.Count == 0)
    {
        <p class="empty-state">No recipes in this category yet. <a href="/submit">Be the first to submit one!</a></p>
    }
    else
    {
        <div class="recipe-list">
            @foreach (var recipe in Recipes)
            {
                <a href="/recipe/@recipe.Id" class="recipe-card">
                    <h3>@recipe.Title</h3>
                    <div class="recipe-meta">
                        <span class="stars">@GetStarDisplay(recipe.AverageRating)</span>
                        <span class="rating-text">@recipe.AverageRating / 5 (@recipe.RatingCount ratings)</span>
                    </div>
                </a>
            }
        </div>
    }
</div>

@code {
    [Parameter]
    public string CategoryName { get; set; } = string.Empty;

    private List<Recipe> Recipes { get; set; } = new();

    protected override void OnParametersSet()
    {
        Recipes = RecipeService.GetRecipesByCategory(CategoryName);
    }

    private string GetStarDisplay(double rating)
    {
        var fullStars = (int)Math.Floor(rating);
        var result = new string('★', fullStars) + new string('☆', 5 - fullStars);
        return result;
    }
}

@page "/recipe/{Id:int}"
@using RecipeCommunity.Services
@using RecipeCommunity.Models

@inject RecipeService RecipeService

<PageTitle>@(Recipe?.Title ?? "Recipe") - Recipe Community</PageTitle>

<div class="container">
    @if (Recipe == null)
    {
        <p class="empty-state">Recipe not found.</p>
    }
    else
    {
        <nav class="breadcrumb">
            <a href="/">Home</a> &rsaquo; <a href="/category/@Uri.EscapeDataString(Recipe.Category)">@Recipe.Category</a> &rsaquo; <span>@Recipe.Title</span>
        </nav>

        <article class="recipe-detail">
            <h1>@Recipe.Title</h1>

            <div class="recipe-meta">
                <span class="rating-text">@Recipe.AverageRating / 5 (@Recipe.RatingCount ratings)</span>
            </div>

            <StarRating RecipeId="Recipe.Id" @rendermode="InteractiveServer" />

            <section class="recipe-section">
                <h2>🧾 Ingredients</h2>
                <ul class="ingredients-list">
                    @foreach (var ingredient in Recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                    {
                        <li>@ingredient</li>
                    }
                </ul>
            </section>

            <section class="recipe-section">
                <h2>👩‍🍳 Steps</h2>
                <ol class="steps-list">
                    @foreach (var step in Recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                    {
                        var text = System.Text.RegularExpressions.Regex.Replace(step, @"^\d+\.\s*", "");
                        <li>@text</li>
                    }
                </ol>
            </section>
        </article>
    }
</div>

@code {
    [Parameter]
    public int Id { get; set; }

    private Recipe? Recipe { get; set; }

    protected override void OnParametersSet()
    {
        Recipe = RecipeService.GetRecipeById(Id);
    }
}

@page "/submit"
@using RecipeCommunity.Services
@using RecipeCommunity.Models
@rendermode InteractiveServer

@inject RecipeService RecipeService

<PageTitle>Submit a Recipe - Recipe Community</PageTitle>

<div class="container">
    <nav class="breadcrumb">
        <a href="/">Home</a> &rsaquo; <span>Submit Recipe</span>
    </nav>

    <h1>Submit a Recipe</h1>

    @if (Submitted)
    {
        <div class="success-message">
            <h2>✅ Recipe Submitted!</h2>
            <p>Thank you for sharing "<strong>@Submission.Title</strong>" with the community.</p>
            <a href="/category/@Uri.EscapeDataString(Submission.Category)">View @Submission.Category recipes</a>
        </div>
    }
    else
    {
        <EditForm Model="Submission" OnValidSubmit="HandleSubmit" class="recipe-form">
            <DataAnnotationsValidator />

            <div class="form-group">
                <label for="title">Recipe Title</label>
                <InputText id="title" @bind-Value="Submission.Title" class="form-control" placeholder="e.g., Grandma's Apple Pie" />
                <ValidationMessage For="@(() => Submission.Title)" />
            </div>

            <div class="form-group">
                <label for="category">Category</label>
                <InputSelect id="category" @bind-Value="Submission.Category" class="form-control">
                    <option value="">-- Select a category --</option>
                    @foreach (var cat in RecipeService.GetCategories())
                    {
                        <option value="@cat.Name">@cat.Name</option>
                    }
                </InputSelect>
                <ValidationMessage For="@(() => Submission.Category)" />
            </div>

            <div class="form-group">
                <label for="ingredients">Ingredients (one per line)</label>
                <InputTextArea id="ingredients" @bind-Value="Submission.Ingredients" class="form-control" rows="6" placeholder="2 cups flour&#10;1 cup sugar&#10;3 eggs" />
                <ValidationMessage For="@(() => Submission.Ingredients)" />
            </div>

            <div class="form-group">
                <label for="steps">Preparation Steps (one per line)</label>
                <InputTextArea id="steps" @bind-Value="Submission.Steps" class="form-control" rows="8" placeholder="1. Preheat oven to 350°F&#10;2. Mix dry ingredients&#10;3. Add wet ingredients" />
                <ValidationMessage For="@(() => Submission.Steps)" />
            </div>

            <button type="submit" class="btn-primary">Submit Recipe</button>
        </EditForm>
    }
</div>

@code {
    private RecipeSubmission Submission { get; set; } = new();
    private bool Submitted { get; set; }

    private void HandleSubmit()
    {
        RecipeService.SubmitRecipe(Submission);
        Submitted = true;
    }
}

@using RecipeCommunity.Services

@inject RecipeService RecipeService

<div class="star-rating">
    <p><strong>Rate this recipe:</strong></p>
    <div class="stars-interactive">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <button class="star-btn @(star <= (HoverRating > 0 ? HoverRating : SelectedRating) ? "filled" : "")"
                    @onclick="() => Rate(star)"
                    @onmouseover="() => HoverRating = star"
