+@using RecipeCommunity.Services
+
+@inject RecipeService RecipeService
+
+<div class="star-rating">
+    <p><strong>Rate this recipe:</strong></p>
+    <div class="stars-interactive">
+        @for (int i = 1; i <= 5; i++)
+        {
+            var star = i;
+            <button class="star-btn @(star <= (HoverRating > 0 ? HoverRating : SelectedRating) ? "filled" : "")"
+                    @onclick="() => Rate(star)"
+                    @onmouseover="() => HoverRating = star"
+                    @onmouseout="() => HoverRating = 0"
+                    disabled="@HasRated">
+                @(star <= (HoverRating > 0 ? HoverRating : SelectedRating) ? "★" : "☆")
+            </button>
+        }
+    </div>
+    @if (HasRated)
+    {
+        <p class="rating-thanks">Thanks! You rated this @SelectedRating out of 5 stars.</p>
+    }
+</div>
+
+@code {
+    [Parameter]
+    public int RecipeId { get; set; }
+
+    private int SelectedRating { get; set; }
+    private int HoverRating { get; set; }
+    private bool HasRated { get; set; }
+
+    private void Rate(int stars)
+    {
+        if (HasRated) return;
+        SelectedRating = stars;
+        HasRated = true;
+        RecipeService.AddRating(RecipeId, stars);
+    }
+}
